305	// TestResolveCLIRenameQueryTransform drives the headline rename behavior the
306	// way a user does: the rule is read from the config file, the request comes
307	// from stdin, and the renamed query is observed inside upstreamURL. Sources
308	// are recognized by decoded name (including "%6Fld"), every duplicate is
309	// renamed in place, an existing target parameter survives, and values, the
310	// no-equals form, empty values and the trailing empty fragment all stay as
311	// they were.
312	func TestResolveCLIRenameQueryTransform(t *testing.T) {
313		config := `{
314		  "routes": [
315		    {"id": "orders", "methods": ["GET"], "pathPrefix": "/api/orders",
316		     "upstream": "http://orders.internal",
317		     "queryTransforms": [{"op": "rename", "name": "old", "to": "new"}]}
318		  ]
319		}`
320		request := `{"method":"GET","target":"/api/orders/7?old=1&new=9&%6Fld=%2f+a=b&old&x=&"}`
321	
322		success := assertResolveSuccess(t, runResolveCLI(t, config, request))
323		if success.RouteID != "orders" {
324			t.Errorf("routeId = %q, want orders", success.RouteID)
325		}
326		wantURL := "http://orders.internal/7?new=1&new=9&new=%2f+a=b&new&x=&"
327		if success.UpstreamURL != wantURL {
328			t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, wantURL)
329		}
330	}
331	
332	// TestResolveCLIRenameNameMatchingAndEncoding covers name comparison and
333	// re-encoding at the command boundary: '+' and percent-encoded spaces name
334	// the same parameter, matching is case-sensitive, a new name with spaces or
335	// non-ASCII bytes is encoded like set, fragments that do not hit keep their
336	// bytes, and renaming a name to itself must not re-encode existing names.
337	func TestResolveCLIRenameNameMatchingAndEncoding(t *testing.T) {
338		rootConfig := func(rule string) string {
339			return `{"routes":[{"id":"root","methods":["*"],"pathPrefix":"/",` +
340				`"upstream":"http://h.internal/base","queryTransforms":[` + rule + `]}]}`
341		}
342		cases := []struct {
343			name    string
344			rule    string
345			target  string
346			wantURL string
347		}{
348			{
349				name:    "plus and percent encoded spaces are the same source name",
350				rule:    `{"op":"rename","name":"a b","to":"c d"}`,
351				target:  "/p?a+b=1&a%20b=2",
352				wantURL: "http://h.internal/base/p?c%20d=1&c%20d=2",
353			},
354			{
355				name:    "matching is case sensitive",
356				rule:    `{"op":"rename","name":"old","to":"new"}`,
357				target:  "/p?OLD=1&old=2",
358				wantURL: "http://h.internal/base/p?OLD=1&new=2",
359			},
360			{
361				name:    "new name with space and non ASCII is encoded, unmatched bytes stay",
362				rule:    `{"op":"rename","name":"old","to":"新 name"}`,
363				target:  "/p?old=1&keep=A%42+z",
364				wantURL: "http://h.internal/base/p?%E6%96%B0%20name=1&keep=A%42+z",
365			},
366			{
367				name:    "same source and target preserves existing name encodings byte for byte",
368				rule:    `{"op":"rename","name":"a b","to":"a b"}`,
369				target:  "/p?a+b=1&a%20b=2&x=",
370				wantURL: "http://h.internal/base/p?a+b=1&a%20b=2&x=",
371			},
372		}
373		for _, tc := range cases {
374			t.Run(tc.name, func(t *testing.T) {
375				request := `{"method":"GET","target":"` + tc.target + `"}`
376				success := assertResolveSuccess(t, runResolveCLI(t, rootConfig(tc.rule), request))
377				if success.RouteID != "root" {
378					t.Errorf("routeId = %q, want root", success.RouteID)
379				}
380				if success.UpstreamURL != tc.wantURL {
381					t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, tc.wantURL)
382				}
383			})
384		}
385	}
386	
387	// TestResolveCLIRenameOnlyOnSelectedRoute proves the rename belongs to the
388	// finally matched route: it neither changes prefix selection nor upstream
389	// path joining, and a losing route's rename is never executed.
390	func TestResolveCLIRenameOnlyOnSelectedRoute(t *testing.T) {
391		// GET /api/orders/7 selects the longer concrete route; the wildcard
392		// route's old->wide rename must not touch the query, and the /7 join
393		// onto a host-only upstream is unchanged.
394		longer := assertResolveSuccess(t, runResolveCLI(t, renameTwoRoutesConfig,
395			`{"method":"GET","target":"/api/orders/7?old=1&new=9&old"}`))
396		if longer.RouteID != "orders" {
397			t.Errorf("routeId = %q, want orders (longest prefix wins)", longer.RouteID)
398		}
399		if want := "http://orders.internal/7?new=1&new=9&new"; longer.UpstreamURL != want {
400			t.Errorf("upstreamURL = %q, want %q", longer.UpstreamURL, want)
401		}
402	
403		// A request only the wide route matches runs that route's own rename and
404		// joins onto its base path normally.
405		wide := assertResolveSuccess(t, runResolveCLI(t, renameTwoRoutesConfig,
406			`{"method":"GET","target":"/api/x?old=1"}`))
407		if wide.RouteID != "wide" {
408			t.Errorf("routeId = %q, want wide", wide.RouteID)
409		}
410		if want := "http://wide.internal/w/x?wide=1"; wide.UpstreamURL != want {
411			t.Errorf("upstreamURL = %q, want %q", wide.UpstreamURL, want)
412		}
413	}
414	
415	// TestResolveCLIRenameThenSetMergesInConfigOrder checks rule ordering through
416	// the CLI: a set on the new name after the rename merges the pre-existing
417	// target parameter and the renamed sources together at the first occurrence,
418	// while unrelated parameters keep their order.
419	func TestResolveCLIRenameThenSetMergesInConfigOrder(t *testing.T) {
420		config := `{"routes":[{"id":"root","methods":["*"],"pathPrefix":"/",` +
421			`"upstream":"http://h.internal/base","queryTransforms":[
422			  {"op":"rename","name":"old","to":"new"},
423			  {"op":"set","name":"new","value":"z"}
424			]}]}`
425		success := assertResolveSuccess(t, runResolveCLI(t, config,
426			`{"method":"GET","target":"/p?new=1&old=2&x=3"}`))
427		if success.RouteID != "root" {
428			t.Errorf("routeId = %q, want root", success.RouteID)
429		}
430		wantURL := "http://h.internal/base/p?new=z&x=3"
431		if success.UpstreamURL != wantURL {
432			t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, wantURL)
433		}
434	}
435	
436	// TestResolveCLIRenameInvalidToRejectsConfig exercises the rename boundary at
437	// the command boundary: a missing, empty or non-string "to" invalidates the
438	// whole configuration even though the offending route can never match the
439	// request. Failure leaves stdout empty and puts one JSON error on stderr whose
440	// reason names the route position, the route's id and the 1-based rule index.
441	func TestResolveCLIRenameInvalidToRejectsConfig(t *testing.T) {
442		cases := []struct {
443			name string
444			bad  string
445		}{
446			{"to missing", `{"op":"rename","name":"a"}`},
447			{"to empty", `{"op":"rename","name":"a","to":""}`},
448			{"to numeric", `{"op":"rename","name":"a","to":7}`},
449			{"to null", `{"op":"rename","name":"a","to":null}`},
450		}
451		for _, tc := range cases {
452			t.Run(tc.name, func(t *testing.T) {
453				// Route 1 ("hit") serves every request via the root prefix;
454				// route 2 ("admin") never matches. A valid set rule precedes the
455				// bad rename, pinning the reported location to rule 2.
456				config := `{
457				  "routes": [
458				    {"id": "hit", "methods": ["*"], "pathPrefix": "/",
459				     "upstream": "http://hit.internal"},
460				    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin",
461				     "upstream": "http://admin.internal",
462				     "queryTransforms": [
463				       {"op": "set", "name": "a", "value": "1"},
464				       ` + tc.bad + `
465				     ]}
466				  ]
467				}`
468				res := runResolveCLI(t, config, `{"method":"GET","target":"/ping?old=1"}`)
469	
470				if res.exitCode == 0 {
471					t.Fatalf("exit code = 0, want non-zero")
472				}
473				if len(res.stdout) != 0 {
474					t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
475				}
476				var fail struct {
477					Code   string `json:"code"`
478					Reason string `json:"reason"`
479				}
480				decodeOneJSON(t, res.stderr, "stderr", &fail)
481				if fail.Code != "invalid_config" {
482					t.Errorf("code = %q, want invalid_config", fail.Code)
483				}
484				for _, want := range []string{"route 2", `"admin"`, "rule 2"} {
485					if !strings.Contains(fail.Reason, want) {
486						t.Errorf("reason = %q, want substring %q (route position, id and 1-based rule index)",
487							fail.Reason, want)
488					}
489				}
490			})
491		}
492	}
493	
494	func TestResolveCLIRouteConflict(t *testing.T) {
495		// alpha and zeta both concretely accept GET at the same /api prefix
496		// with no longer prefix to win; the same-prefix wildcard route must not
497		// appear among the final candidates.
498		config := `{
499		  "routes": [
500		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://z.internal/v1"},
501		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://a.internal/v1"},
502		    {"id": "wild",  "methods": ["*"],   "pathPrefix": "/api", "upstream": "http://w.internal/v1"}
503		  ]
504		}`
505		res := runResolveCLI(t, config, cliSuccessRequest)
506	
507		if res.exitCode == 0 {
508			t.Fatalf("exit code = 0, want non-zero")
509		}
510		if len(res.stdout) != 0 {
511			t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
512		}
513	
514		var fail struct {
515			Code       string   `json:"code"`
516			Reason     string   `json:"reason"`
517			Candidates []string `json:"candidates"`
518		}
519		decodeOneJSON(t, res.stderr, "stderr", &fail)
520		if fail.Code != "route_conflict" {
521			t.Errorf("code = %q, want route_conflict", fail.Code)
522		}
523		if fail.Reason == "" {
524			t.Fatal("reason must be non-empty")
525		}
526		wantCandidates := []string{"alpha", "zeta"}
527		if !reflect.DeepEqual(fail.Candidates, wantCandidates) {
