418		routes := []string{
419			`{"id":"short-get","methods":["GET"],"pathPrefix":"/a","upstream":"http://short.internal"}`,
420			`{"id":"long-wild","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal/w"}`,
421			`{"id":"long-get","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://exact.internal/e"}`,
422		}
423		for _, order := range [][]string{routes, reversed(routes)} {
424			cfg := mustConfig(t, configFromRoutes(order...))
425	
426			res := resolveJSON(t, cfg, `{"method":"GET","target":"/a/b/1"}`)
427			if res.RouteID != "long-get" || res.UpstreamURL != "http://exact.internal/e/1" {
428				t.Fatalf("GET: got %+v, want long-get / http://exact.internal/e/1", res)
429			}
430	
431			// Methods without a concrete entry at the longest prefix still fall
432			// to the wildcard route there, never to the shorter-prefix GET.
433			for _, method := range []string{"POST", "PROPFIND"} {
434				res := resolveJSON(t, cfg, `{"method":"`+method+`","target":"/a/b/1"}`)
435				if res.RouteID != "long-wild" || res.UpstreamURL != "http://wild.internal/w/1" {
436					t.Fatalf("%s: got %+v, want long-wild / http://wild.internal/w/1", method, res)
437				}
438			}
439		}
440	}
