442	func TestResolveRouteWithConcreteAndWildcardCountsOnce(t *testing.T) {
443		// A route whose methods list holds both GET and * is a concrete match
444		// for GET, and it is one candidate: matching two method entries of its
445		// own must not turn into a self-conflict.
446		single := mustConfig(t, `{"routes":[
447		  {"id":"dual","methods":["GET","*"],"pathPrefix":"/d","upstream":"http://dual.internal/base"}
448		]}`)
449		for _, method := range []string{"GET", "POST"} {
450			res := resolveJSON(t, single, `{"method":"`+method+`","target":"/d/x"}`)
451			if res.RouteID != "dual" || res.UpstreamURL != "http://dual.internal/base/x" {
452				t.Fatalf("%s: got %+v, want dual / http://dual.internal/base/x", method, res)
453			}
454		}
455	
456		// Next to a plain wildcard route on the same prefix, the dual route is
457		// the concrete winner for GET; for other methods both are wildcard
458		// candidates and conflict as exactly two routes.
459		routes := []string{
460			`{"id":"dual","methods":["GET","*"],"pathPrefix":"/d","upstream":"http://dual.internal/base"}`,
461			`{"id":"wild","methods":["*"],"pathPrefix":"/d","upstream":"http://wild.internal"}`,
462		}
463		for _, order := range [][]string{routes, reversed(routes)} {
464			cfg := mustConfig(t, configFromRoutes(order...))
465	
466			res := resolveJSON(t, cfg, `{"method":"GET","target":"/d/x"}`)
467			if res.RouteID != "dual" {
468				t.Fatalf("GET: routeId = %q, want dual (concrete entry wins)", res.RouteID)
469			}
470	
471			_, rf := Resolve(cfg, mustReq(t, "POST", "/d/x"))
472			if rf == nil || rf.Code != "route_conflict" {
473				t.Fatalf("POST: got %+v, want route_conflict", rf)
474			}
475			if want := []string{"dual", "wild"}; !equalStrings(rf.Candidates, want) {
476				t.Fatalf("POST: candidates = %v, want %v (one entry per route)", rf.Candidates, want)
477			}
478		}
479	}
