611	func TestInvalidConfigFieldTypes(t *testing.T) {
612		// Unlike TestInvalidConfig's missing/illegal-value cases, these exercise
613		// fields whose JSON type itself is wrong: valid JSON that cannot satisfy
614		// the field's type must still be invalid_config, but the reason has to
615		// name the route position (and a valid string id), distinguish it from a
616		// JSON syntax failure, and say why the field could not be read.
617		goodRoute := `"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"`
618	
619		cases := []struct {
620			name      string
621			src       string
622			want      []string // all must appear in the reason
623			forbidden []string // none may appear in the reason
624		}{
625			{
626				name: "methods string on second route, id after the bad field",
627				src: `{"routes":[
628				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://a"},
629				  {"methods":"GET","id":"orders","pathPrefix":"/api/orders","upstream":"http://o"}
630				]}`,
631				want: []string{"route 2", `"orders"`, "methods must be an array"},
632			},
633			{
634				name: "methods null",
635				src:  `{"routes":[{` + goodRoute + `,"methods":null}]}`,
636				want: []string{"route 1", `"x"`, "methods must be an array"},
637			},
638			{
639				name: "methods is an object",
640				src:  `{"routes":[{` + goodRoute + `,"methods":{"GET":true}}]}`,
641				want: []string{"route 1", `"x"`, "methods must be an array"},
642			},
643			{
644				name: "numeric entry inside a legal methods array",
645				src: `{"routes":[
646				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://a"},
647				  {"id":"orders","methods":["GET",1],"pathPrefix":"/api/orders","upstream":"http://o"}
648				]}`,
649				want: []string{"route 2", `"orders"`, "methods entry 2 must be a string"},
650			},
651			{
652				name: "null entry inside methods",
653				src:  `{"routes":[{` + goodRoute + `,"methods":[null]}]}`,
654				want: []string{"route 1", "methods entry 1 must be a string"},
655			},
656			{
657				name:      "id is a number",
658				src:       `{"routes":[{"id":1,"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
659				want:      []string{"route 1", "id must be a string"},
660				forbidden: []string{"(id "},
661			},
662			{
663				name:      "id is an object",
664				src:       `{"routes":[{"id":{"v":1},"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
665				want:      []string{"route 1", "id must be a string"},
666				forbidden: []string{"(id "},
667			},
668			{
669				name: "pathPrefix is a number, id written after it",
670				src:  `{"routes":[{"methods":["GET"],"pathPrefix":1,"id":"orders","upstream":"http://o"}]}`,
671				want: []string{"route 1", `"orders"`, "pathPrefix must be a string"},
672			},
673			{
674				name: "upstream is a boolean, id written after it",
675				src:  `{"routes":[{"methods":["GET"],"pathPrefix":"/a","upstream":true,"id":"orders"}]}`,
676				want: []string{"route 1", `"orders"`, "upstream must be a string"},
677			},
678			{
679				name: "routes entry is not an object",
680				src:  `{"routes":[42]}`,
681				want: []string{"route 1", "route entry must be a JSON object"},
682			},
683		}
684		for _, tc := range cases {
685			t.Run(tc.name, func(t *testing.T) {
686				_, f := ParseConfig([]byte(tc.src))
687				if f == nil {
688					t.Fatalf("expected invalid_config")
689				}
690				if f.Code != "invalid_config" {
691					t.Fatalf("code = %q, want invalid_config", f.Code)
692				}
693				if strings.Contains(f.Reason, "not valid JSON") {
694					t.Fatalf("field type error must not be described as a JSON syntax failure: %q", f.Reason)
695				}
696				for _, want := range tc.want {
697					if !strings.Contains(f.Reason, want) {
698						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
699					}
700				}
701				for _, bad := range tc.forbidden {
702					if strings.Contains(f.Reason, bad) {
703						t.Fatalf("reason = %q must not contain %q", f.Reason, bad)
704					}
705				}
706			})
707		}
708	
709		// Broken JSON syntax stays a parse failure and never gets a guessed
710		// route position, even when the corruption is inside the routes array.
711		for _, src := range []string{`{not json`, `{"routes": [{"id":"x"} broken`} {
712			_, f := ParseConfig([]byte(src))
713			if f == nil || f.Code != "invalid_config" {
714				t.Fatalf("got %+v, want invalid_config for %q", f, src)
715			}
716			if !strings.Contains(f.Reason, "not valid JSON") {
717				t.Fatalf("reason = %q, want a JSON parse failure", f.Reason)
718			}
719			if strings.Contains(f.Reason, "route 1") {
720				t.Fatalf("syntax failure must not guess a route position: %q", f.Reason)
721			}
722		}
723	
724		// Fixing the second route's methods lets the request resolve normally,
725		// including through the first route it originally matched.
726		cfg := mustConfig(t, `{"routes":[
727		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
728		  {"id":"orders","methods":["GET"],"pathPrefix":"/api/orders","upstream":"http://orders.internal"}
729		]}`)
730		res := resolveJSON(t, cfg, `{"method":"GET","target":"/api/items"}`)
731		if res.RouteID != "api" || res.UpstreamURL != "http://api.internal/v1/items" {
732			t.Fatalf("got %+v, want api / http://api.internal/v1/items", res)
733		}
734	}
